sys_script_include.script:
var resubmitcatalogitem3 = Class.create();
resubmitcatalogitem3.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    resubmitcatalogitemdaction: function() {
        try {
            // 获取请求参数
            var ritmID = this.getParameter("sys_id");
            var taskid = this.getParameter("task_id");
            var additional_information = this.getParameter("additional_information");

            // 查询请求项记录
            var now_GR = new GlideRecord("sc_req_item");
            now_GR.get(ritmID);

            // 根据当前状态设置新状态
            if (now_GR.state == 9) {
                now_GR.state = 1;
            } else if (now_GR.state == 3) {
                now_GR.state = 1;
            } else {
                now_GR.state = 2;
            }

            // 更新附加信息字段
            now_GR.variables.additional_information = additional_information;
            now_GR.update();

            // 如果状态变为2，更新关联任务
            if (now_GR.state == 2) {
                var now_task = new GlideRecord("task");
                now_task.get(taskid);
                now_task.state = 2;
                now_task.update();
            }

        } catch (e) {
            gs.error("GetDefaultVariables 异常：" + e);
            return 'exception';
        }
    },
    type: 'resubmitcatalogitem3'
});
